const overlays = layers => layers.map((d, index) => (d ? `<path d="${d}" fill="${SPIDER.steps[index][0]}" fill-opacity="${SPIDER.steps[index][1]}"/>` : '')).join('')
const drawn = (part, paint) => `<path d="${part.body}" fill="${paint}"/>${overlays(part.layers)}`
const legs = (near, paint) => SPIDER.parts.filter(part => part.pivot && Boolean(part.near) === near)
  .map(part => `<g class="bt-leg" data-leg="${part.id}" style="transform-origin:${part.pivot[0]}px ${part.pivot[1]}px">${drawn(part, paint)}</g>`).join('')

// The eyes are the artwork's, drawn on top of the body (`solidEyes`) instead of being cut
// out of it, so the mark blinks and glances like every other character. The violet ink
// shows the artwork's own purple in both themes. A mark's motion is measured against the
// body's box, so an unpainted box of the picture this drawing replaced keeps the whole
// figure's motion as it was. `rig` draws the parts for a mark whose legs move
// (spider-motion.js): that box, the far legs, which go behind the torso and move with it,
// the torso, and the near legs, which stand in front.
const BOX = '<rect x="-30.2083" y="-4.5833" width="160" height="106.6667" fill="none"/>'
export const SPIDER_SHAPE = {
  label: 'Muse Spider',
  size: 100,
  solidEyes: true,
  eyes: [[54.6, 47.4, 16.8, 17.7, -8], [74.3, 45.9, 15, 18.3, -8]],
  path: SPIDER.body,
  layers: overlays(SPIDER.layers) + BOX,
  inks: { violet: SPIDER.base },
  rig: {
    box: BOX,
    back: paint => legs(false, paint),
    torso: paint => drawn(SPIDER.parts.find(part => part.id === 'torso'), paint),
    front: paint => legs(true, paint),
  },
}
